    ("results/exp070_qwen7b_logiqa200/exp070_results.json", "exp070", "Qwen2.5-7B", "LogiQA-200"),
    ("results/exp069_llama8b_logiqa200/exp069_results.json", "exp069l", "LLaMA-3.1-8B", "LogiQA-200"),
